    /**
     * Refuses a program whose types break a comprises clause of its main
     * component.  A trait or object of the program that explicitly extends a
     * trait with a comprises clause declared in main must be a subtype of a
     * type the clause lists, or a trait with a comprises clause of its own each
     * of whose listed types meets this requirement, or a trait with static
     * parameters that at least one trait or object of the program extends,
     * each of them a subtype of a listed type.  Types are read from the
     * declarations as written, each name resolved in its declaration's
     * environment and each static parameter replaced by the static argument
     * given it.  Then refuses a program one of whose traits or objects
     * breaks the Meet Rule for Functional Methods
     * (OverloadedFunction.FunctionalMethodMeets), one with static parameters
     * for every instance (checkGenericFunctionalMethodMeets).
     */
    /**
     * Refuses a program that writes a numeral type, NaturalNumeral or
     * RadixPointNumeral, as a type that a trait, an object or an object
     * expression extends, as a type that a trait's comprises clause lists, or
     * as a static argument: a numeral type is written only as a parameter's
     * type (literals.tex, "Literals").  The libraries' own components declare
     * the numeral types and are not read.
     */
    public static void checkNumeralTypesWritten(List<? extends CUWrapper> units) {
        for (CUWrapper u : units) {
            CompilationUnit cu = u.getCompilationUnit();
            if (WellKnownNames.exportsDefaultLibrary(NodeUtil.nameString(cu.getName()))) continue;
            cu.accept(new NodeDepthFirstVisitor_void() {
                @Override
                public void forTraitTypeWhere(TraitTypeWhere that) {
                    refuseNumeralType(that.getBaseType());
                    super.forTraitTypeWhere(that);
                }

                @Override
                public void forTypeArg(TypeArg that) {
                    refuseNumeralType(that.getTypeArg());
                    super.forTypeArg(that);
                }

                @Override
                public void forTraitDecl(TraitDecl that) {
                    if (that.getComprisesClause().isSome()) {
                        for (NamedType t : that.getComprisesClause().unwrap()) refuseNumeralType(t);
                    }
                    super.forTraitDecl(that);
                }
            });
        }
    }

    private static void refuseNumeralType(Type t) {
        if (!(t instanceof TraitType)) return;
        Id name = ((TraitType) t).getName();
        String text = name.getText();
        if (!text.equals("NaturalNumeral") && !text.equals("RadixPointNumeral")) return;
        if (name.getApiName().isSome() && !WellKnownNames.exportsDefaultLibrary(name.getApiName().unwrap().getText())) return;
        error(t, errorMsg(text, " cannot be written in a program except as a parameter's type."));
    }

